import json

def citations(obj):
    for r in obj.get('results', []) or []:
        data=(r.get('response') or {}).get('data') or {}
        for c in data.get('citations', []) or []:
            yield {'url':c.get('url'),'title':c.get('title'),'snippet':c.get('snippet')}

def fetch_rows(obj):
    for r in obj.get('results', []) or []:
        data=(r.get('response') or {}).get('data') or {}
        sts={s.get('id') or s.get('url'):s for s in (data.get('statuses') or [])}
        for p in (data.get('results') or []) or []:
            st=sts.get(p.get('id')) or sts.get(p.get('url')) or {}
            yield {'url':p.get('url'),'status':st.get('status'),'http':((st.get('error') or {}).get('httpStatusCode')),'tag':((st.get('error') or {}).get('tag')),'title':p.get('title'),'summary':p.get('summary')}

